  MV.ASSETS.push(...P([
  { id: "ie-rail-cross-subsidy", type: "concept", domain: "economics", region: "india", title: "Goods trains pay for your cheap ticket", value: 4, cue: "train fares, railway losses, or why freight moves by road",
    emoji: "🚂", wiki: "Indian Railways",
    fact: "Indian Railways runs about 13,000 passenger trains a day. It loses money on almost all of them. In 2022-23 it said passengers paid only about 53% of the real cost of their trips, a gap of about 57,000 crore rupees. Goods trains fill that gap.",
    why: "The cheap ticket you buy is paid for by every truck-load of coal, cement and steel that moves by rail. The two are joined.",
    mech: "Fares are kept low because raising them is unpopular. So freight is charged well above its cost, often said to be around 150% of cost. This is called a cross-subsidy. But high freight rates push cement and goods companies onto trucks. Railways then carries less freight, which makes the gap harder to close.",
    models: ["incentives", "second-order-thinking", "feedback-loops"],
    q: "How does Indian Railways afford such low passenger fares?",
    a: "Passenger fares cover only about half of the cost. Freight is charged far above cost to fill the gap, a cross-subsidy. The high freight rates then push goods onto trucks, which shrinks the money that pays for the subsidy.",
    chain: [["Passenger fares cover only about half the cost", ["half", "53", "loss", "below cost", "subsid"]], ["Freight is charged above cost to fill the gap", ["freight", "goods", "cross", "above cost", "150"]], ["High freight rates push goods onto trucks", ["truck", "road", "push", "lose"]], ["Less freight makes the gap harder to close", ["harder", "shrink", "less freight", "gap"]]],
    mcq: { q: "What pays for the loss on Indian Railways passenger fares?", o: ["High charges on freight such as coal and cement", "Ticket sales on premium trains alone", "Advertising inside stations", "Foreign loans every year"] },
    bring: "When someone says train tickets are cheap: “They are. A goods train somewhere is paying about half of your fare.”",
    follow: "Should a fare cover its cost, or is cheap travel worth the loss?",
    deeper: "Coal is the single biggest item Indian Railways carries. Freight earns about two thirds of its total income, though it is a small share of the trains you see." },

  { id: "ie-india-post", type: "fact", domain: "business", region: "india", title: "India Post: 1.6 lakh offices, mostly in villages", value: 3, cue: "post offices, speed post, or reaching remote villages",
    emoji: "📮", wiki: "India Post",
    fact: "India has the largest postal network in the world, with about 1.6 lakh post offices. Around nine out of ten of them are in villages. On average, a post office serves about 8,000 people.",
    why: "No bank, courier or shop has reached as deep into rural India. That is why the state keeps using it for new jobs, from savings to payments.",
    mech: "The network was built over 170 years for letters, when there was no other way to send a message. Letters have fallen, but the buildings and postmen remain. A network that is already paid for is cheap to reuse. So post offices now sell savings schemes, insurance and, since 2018, run India Post Payments Bank. The reach that letters built is now worth more than the letters.",
    models: ["network-effects", "lindy-effect"],
    q: "Why does India Post still matter when few people send letters?",
    a: "Its 1.6 lakh offices, mostly in villages, reach deeper than any bank or courier. The network was already built and paid for, so it is cheap to reuse for savings, insurance and payments banking.",
    chain: [["About 1.6 lakh offices, mostly rural", ["1.6 lakh", "160", "village", "rural", "nine out of ten", "largest"]], ["Built for letters, which have fallen", ["letter", "built", "170"]], ["An existing network is cheap to reuse", ["reuse", "already", "cheap", "paid for"]], ["Now used for savings, insurance and payments", ["saving", "insurance", "payment", "bank"]]],
    mcq: { q: "Roughly what share of India's post offices are in rural areas?", o: ["About 90%", "About 50%", "About 25%", "About 10%"] },
    bring: "When a courier fails to find an address: “The post office has 1.6 lakh branches. Nine in ten are in villages where no courier goes.”",
    follow: "What else could a network that reaches every village be used for?",
    deeper: "Post Office savings schemes hold lakhs of crore of rupees. For many villagers the postman, not a bank clerk, is the face of the financial system." },

  { id: "ie-kirana", type: "business concept", domain: "business", region: "india", title: "Why 1.2 crore kirana shops survive", value: 5, cue: "the local shop, quick-commerce apps, or supermarkets",
    emoji: "🏪", wiki: "Kirana",
    fact: "India has around 1.2 crore kirana stores, the small family-run grocery shops on every street. Despite supermarkets and delivery apps, they still handle most of India's grocery sales, often estimated at 80 to 90%.",
    why: "Experts have predicted the death of the kirana for 25 years. It keeps winning. The reasons tell you a lot about how India really shops.",
    mech: "A kirana has almost no costs. The owner's family does the work, and the shop is often part of their home, so there is no rent or salary. The owner knows each customer and gives credit, called udhaar, until payday. He delivers a single packet of milk by hand for free. Supermarkets must pay rent, staff and tax on every item, so they cannot match these prices on small orders. Big companies also need kiranas, because that is where their biscuits and shampoo sachets actually sell.",
    models: ["moat", "incentives", "first-principles"],
    q: "Why have supermarkets and apps not replaced the kirana store?",
    a: "A kirana has almost no cost: family labour, no rent and no payroll. It gives credit until payday and delivers small orders by hand. Supermarkets carry rent, staff and tax, so they cannot match it on small purchases.",
    chain: [["Around 1.2 crore shops with most grocery sales", ["1.2 crore", "12 million", "most", "80", "90"]], ["Almost no costs: family labour and no rent", ["family", "rent", "no cost", "salary", "home"]], ["Credit and free delivery of small orders", ["credit", "udhaar", "deliver", "small order", "single"]], ["Supermarkets carry costs they cannot drop", ["supermarket", "staff", "tax", "cannot match"]]],
    mcq: { q: "What is one key reason kirana stores can beat supermarkets on price?", o: ["Family labour and a shop inside the home mean almost no fixed costs", "They import goods directly from China", "They do not pay for the goods they sell", "The government pays them a monthly grant"] },
    bring: "When a new quick-commerce app is praised: “The kirana has survived every one of these. It has no rent, no payroll and gives udhaar.”",
    follow: "Does your local shop still give credit? Would an app ever do that?",
    deeper: "The kirana is also the biggest distribution network for companies like Hindustan Unilever and Parle. Delivery apps now often use kiranas as their local store rooms, instead of fighting them." },

  { id: "ie-informal-economy", type: "concept", domain: "economics", region: "india", title: "Nine out of ten Indian workers are informal", value: 5, cue: "job security, domestic help, daily-wage work, or the lockdown",
    emoji: "👷", wiki: "Informal economy",
    fact: "About 90% of India's workers are informal. They have no written contract, no paid leave, no provident fund and no health cover from an employer. That is over 40 crore people: the maid, the driver, the construction worker, the hawker and most small shop staff.",
    why: "When the 2020 lockdown began, millions walked home because they had no job to return to and no safety net. This number explains why.",
    mech: "Most Indian businesses are tiny: a shop, a workshop with five people, a farm. Labour laws and taxes apply mainly to registered firms, so staying small and unregistered is cheaper. Workers in such places get paid cash by the day or the month. The state cannot see them, so it cannot easily tax them or protect them. When work stops, income stops the same day.",
    models: ["incentives", "margin-of-safety", "map-vs-territory"],
    q: "What does it mean that most Indian workers are informal, and why is it so?",
    a: "About 90% have no contract, paid leave or provident fund. Most businesses are tiny and unregistered because that is cheaper, so workers are paid in cash with no safety net. When work stops, income stops at once.",
    chain: [["About 90% of workers are informal", ["90", "nine out of ten", "informal", "40 crore"]], ["No contract, leave or provident fund", ["contract", "leave", "provident", "pf", "cover", "security"]], ["Tiny unregistered businesses are cheaper to run", ["tiny", "small", "unregistered", "cheaper", "register"]], ["When work stops, income stops", ["stop", "safety net", "same day", "cash"]]],
    mcq: { q: "Roughly what share of India's workers have no formal contract or social security?", o: ["About 90%", "About 60%", "About 30%", "About 10%"] },
    bring: "When job security comes up: “Nine out of ten Indian workers have no contract at all. We in offices are the rare ones.”",
    follow: "How many people who work for you or your building are on a written contract?",
    deeper: "The 2017-18 labour survey found about 411 of 461 million workers were informal. Even inside registered companies, many workers are hired through contractors and remain informal." },

  { id: "ie-ration-pds", type: "concept", domain: "economics", region: "india", title: "The ration shop: free grain for 81 crore people", value: 4, cue: "ration cards, food prices, or welfare for the poor",
    emoji: "🌾", wiki: "Public distribution system",
    fact: "India's public distribution system gives 5 kg of rice or wheat a month to about 81 crore people, free of charge since 2023. It works through about 5.4 lakh fair price shops, the ration shops. It is the largest food programme in the world.",
    why: "Almost six in ten Indians get grain from this system. It shapes what the government buys from farmers and what it stores.",
    mech: "The government buys wheat and rice from farmers at a fixed support price. The Food Corporation of India stores it in giant godowns. Grain then travels by train and truck to state warehouses and to the ration shops. A ration card, now linked to Aadhaar, tells the shop who may collect. Since 2019, the One Nation One Ration Card scheme lets a migrant worker collect in any state, because the card is checked by fingerprint on a machine.",
    models: ["bottlenecks", "second-order-thinking"],
    q: "How does grain reach a ration shop, and what changed with One Nation One Ration Card?",
    a: "The government buys wheat and rice at a support price, the FCI stores it, and it moves to 5.4 lakh ration shops. About 81 crore people get 5 kg a month free. With Aadhaar-linked cards, a migrant can now collect in any state.",
    chain: [["About 81 crore people get 5 kg a month", ["81 crore", "5 kg", "free", "largest"]], ["Government buys grain at a support price and FCI stores it", ["support price", "fci", "food corporation", "store", "godown", "buys"]], ["Distributed through 5.4 lakh ration shops", ["5.4 lakh", "ration shop", "fair price"]], ["Aadhaar-linked cards work in any state", ["aadhaar", "any state", "one nation", "migrant", "fingerprint"]]],
    mcq: { q: "About how many people receive grain through India's ration system?", o: ["About 81 crore", "About 20 crore", "About 5 crore", "About 130 crore"] },
    bring: "When food prices come up: “Eighty-one crore people get 5 kg of grain free every month. That is the biggest food scheme on Earth.”",
    follow: "Do you know anyone whose household depends on the ration shop?",
    deeper: "Before 2023 the grain cost 2 or 3 rupees a kilo. The free grain was first added during Covid in 2020 and has been extended until the end of 2028." },

  { id: "ie-msp", type: "concept", domain: "economics", region: "india", title: "MSP: the promised price for wheat and rice", value: 4, cue: "farmer protests, wheat and rice prices, or Punjab's fields",
    emoji: "🌾", wiki: "Minimum Support Price",
    fact: "The minimum support price, or MSP, is a price the government announces for 22 crops before each season. It promises to buy at that price if the market pays less. In practice, most buying is of wheat and rice, and most of it happens in a few states such as Punjab, Haryana and Madhya Pradesh.",
    why: "MSP decides what millions of farmers plant. It also decides what the ration shops hold and how much water Punjab pumps.",
    mech: "A guaranteed buyer at a known price removes risk. So farmers in states with good procurement grow wheat and rice year after year, even where water is scarce. Pulses and oilseeds have an MSP on paper but little actual buying, so fewer farmers grow them, and India imports both. A 2015 government committee estimated that only around 6% of farmers had sold any crop to the government at MSP. Who benefits depends on where you farm and what you grow.",
    models: ["incentives", "second-order-thinking", "goodharts-law"],
    q: "What is MSP, and how does it shape what farmers grow?",
    a: "MSP is a price at which the government promises to buy a crop. Because actual buying is mostly wheat and rice in a few states, farmers there grow those crops repeatedly, even with scarce water, while pulses and oilseeds get little support and are imported.",
    chain: [["A promised government price for 22 crops", ["promise", "guarantee", "22", "announce", "support price"]], ["Actual buying is mostly wheat and rice in a few states", ["wheat", "rice", "punjab", "haryana", "few states", "procure"]], ["A sure buyer pushes farmers to grow those crops", ["grow", "plant", "year after year", "risk", "repeat"]], ["Little buying of pulses and oilseeds, so India imports them", ["pulse", "oilseed", "import", "little"]]],
    mcq: { q: "Which crops get most of the actual government buying at MSP?", o: ["Wheat and rice", "Pulses and oilseeds", "Cotton and sugarcane", "Fruits and vegetables"] },
    bring: "When farmer protests are in the news: “MSP is a promise to buy. The fight is about who the promise really reaches.”",
    follow: "Why do you think Punjab grows rice when it is not a rice-eating state?",
    deeper: "The prices are proposed by the Commission for Agricultural Costs and Prices. A long-running debate asks whether the formula should include the cost of the farmer's own land and family labour, called C2." },

  { id: "ie-ujjwala-lpg", type: "fact", domain: "economics", region: "india", title: "Ujjwala: 10 crore gas connections, and the refill question", value: 4, cue: "cooking gas, cylinder prices, or smoke in village kitchens",
    emoji: "🔥", wiki: "Pradhan Mantri Ujjwala Yojana",
    fact: "In 2016 the Ujjwala scheme began giving free LPG connections to poor households, with the deposit paid by the state. By 2025 it had given over 10 crore connections. Around 60 to 65% of the LPG India burns is imported, mostly from the Gulf.",
    why: "Smoke from wood and dung stoves harms the lungs of millions of women. But a connection is only useful if the family can afford the next cylinder.",
    mech: "The scheme solved the first problem, the deposit and stove cost, which had kept poor homes away from LPG. The second problem is the refill. A cylinder costs several hundred rupees, and wood is free. So studies found many Ujjwala homes refilled only a few times a year, and kept using wood alongside gas. The government then added a subsidy per cylinder for these homes. Because most LPG is imported, the price also moves with world oil and the rupee.",
    models: ["incentives", "second-order-thinking", "bottlenecks"],
    q: "What did Ujjwala solve, and what problem remained?",
    a: "It paid the connection deposit, which had kept poor families away from LPG, and gave over 10 crore connections. But a refill costs several hundred rupees while wood is free, so many homes refilled rarely. A per-cylinder subsidy was later added, and the price still depends on imports.",
    chain: [["Free connections for poor households since 2016", ["2016", "free connection", "deposit", "10 crore"]], ["Refills cost money while wood is free", ["refill", "wood", "free", "afford", "several hundred"]], ["Many homes refilled rarely, so a subsidy was added", ["rarely", "few times", "subsidy", "per cylinder"]], ["Most LPG is imported, so the price follows oil", ["import", "gulf", "60", "oil", "rupee"]]],
    mcq: { q: "What was the main hurdle after a poor family got an Ujjwala connection?", o: ["Paying for refill cylinders", "Finding a shop that sold stoves", "Getting an electricity connection", "Learning to read the gas meter"] },
    bring: "When cylinder prices rise: “Ten crore families got a free connection. The real test is whether they can pay for the next refill.”",
    follow: "If wood is free and gas costs money, what would make you switch?",
    deeper: "The scheme was launched on 1 May 2016 at Ballia in Uttar Pradesh. India imports about 20 million tonnes of LPG a year, around 90% of it from the Middle East." },

  { id: "ie-blackout-2012", type: "historical story", domain: "history", region: "india", title: "July 2012: the largest blackout in history", value: 5, cue: "power cuts, the national grid, or very big failures", story: "ie-grid",
    emoji: "🔌", wiki: "2012 India blackouts",
    fact: "On 30 and 31 July 2012, India's northern, eastern and north-eastern power grids collapsed. About 62 crore people, nearly a tenth of the world, lost power. It remains the largest blackout in history. In December 2013 the southern grid was joined to the rest, making one national grid.",
    why: "It showed that a grid is one machine. If a few states pull too much, the whole thing can trip, from Punjab to Assam.",
    mech: "The monsoon was weak that July, so farmers ran pumps and cities ran fans and coolers. Several northern states drew far more power than they were allotted. A key 400 kV line near Gwalior tripped. Its load jumped onto other lines, which tripped in turn, like a row of falling dominoes. Within minutes three grids were dark. Trains stopped, miners were trapped underground, and hospitals ran on diesel. Afterwards, penalties for over-drawing were tightened and the last separate grid, the southern one, was joined to form one national grid in 2013.",
    models: ["feedback-loops", "margin-of-safety", "incentives"],
    q: "What caused the 2012 blackout, and what changed after it?",
    a: "A weak monsoon raised demand, northern states drew more than their share, and a key line near Gwalior tripped. Its load cascaded onto other lines until three grids collapsed, cutting power to about 62 crore people. Rules on over-drawing were tightened and in 2013 the southern grid was joined to make one national grid.",
    chain: [["Weak monsoon raised demand and states over-drew power", ["monsoon", "over", "more than", "drew", "allot", "pump"]], ["One key line tripped near Gwalior", ["line", "gwalior", "tripped", "400"]], ["The load cascaded and three grids collapsed", ["cascad", "domino", "three grids", "collapse", "jumped"]], ["About 62 crore people lost power; one grid formed in 2013", ["62 crore", "620", "tenth", "2013", "national grid", "one grid"]]],
    mcq: { q: "Roughly how many people lost power in the July 2012 blackout?", o: ["About 62 crore", "About 5 crore", "About 20 crore", "About 130 crore"] },
    bring: "When the lights go out: “In July 2012 the lights went out for 62 crore people at once. Half the country.”",
    follow: "Why do you think Mumbai was not affected that day?",
    deeper: "Mumbai has an islanding system that cuts it off from the grid when the grid becomes unstable, so the city stayed lit in 2012. India's grid is now one of the largest single synchronised grids in the world." },

  { id: "ie-discom-losses", type: "concept", domain: "economics", region: "india", title: "Why electricity companies lose money", value: 4, cue: "power cuts, electricity bills, or free power promises",
    emoji: "💡", wiki: "Electricity sector in India",
    fact: "India's state power distribution companies, called discoms, had piled up losses of about 6.9 lakh crore rupees by 2024. About 15% of the electricity they buy is never paid for, down from over 22% a decade earlier.",
    why: "A discom that loses money cannot pay the power plant. The plant then cannot buy coal. Your power cut often begins on a balance sheet.",
    mech: "Discoms buy power from generators and sell it to homes, farms and factories. Farmers in many states get power free or almost free, and homes pay below cost. To make up for it, factories and shops are charged far above cost. Some power is lost in old wires, and some is stolen or never billed. States promise to pay the discom for the subsidies but often pay late. So the discom falls behind on its own bills, borrows, and cuts supply to save money.",
    models: ["incentives", "feedback-loops", "second-order-thinking"],
    q: "Why do India's power distribution companies lose money?",
    a: "They sell power to farmers and homes below cost, charge factories above cost to make up for it, and lose about 15% of power to theft, old wires and unpaid bills. States pay the promised subsidy late, so discoms fall behind, borrow and cut supply.",
    chain: [["Farms and homes pay below cost", ["farm", "free", "below cost", "home", "subsid"]], ["Factories are charged above cost to make up", ["factor", "shop", "above cost", "industr", "make up"]], ["About 15% of power is lost, stolen or unbilled", ["15", "lost", "theft", "stolen", "unbilled", "never paid", "wires"]], ["Late state payments lead to debt and power cuts", ["late", "borrow", "debt", "cut", "fall behind", "6.9"]]],
    mcq: { q: "Why are factories charged more than cost for electricity in most Indian states?", o: ["To make up for power sold to farms and homes below cost", "Because factories use power at night", "Because the law bans cheap power for industry", "Because factories are far from power plants"] },
    bring: "When free electricity is promised: “Someone pays. Usually it is the factory next door, or the discom that then cannot pay for coal.”",
    follow: "Who do you think should pay for cheap power to farmers?",
    deeper: "The unpaid share is called AT&C loss, for aggregate technical and commercial loss. In 2024-25 the discoms together reported a small profit for the first time in years, though their old debt remains." },

  { id: "ie-golden-quadrilateral", type: "fact", domain: "geography", region: "india", title: "The Golden Quadrilateral", value: 4, cue: "highways, road trips, or trucks on the Mumbai-Pune road",
    emoji: "🛣️", wiki: "Golden Quadrilateral",
    fact: "The Golden Quadrilateral is a 5,846 km network of four to six lane highways joining Delhi, Mumbai, Chennai and Kolkata. Work began in 2001 and finished in 2012. It was India's biggest road project since independence.",
    why: "Most Indian goods still move by truck. A faster road between the four big cities changes where factories are built and how long your parcel takes.",
    mech: "Before 2001, national highways were mostly two lanes, shared with bullock carts and buses. Trucks averaged well under 40 km an hour. Wider, divided roads let trucks run faster and safer. Studies found factories grew along the new route, especially in districts that were far from big cities before. The project was paid for partly by a small cess, a tax, on every litre of petrol and diesel, so drivers paid for the roads they would use.",
    models: ["network-effects", "compounding"],
    q: "What is the Golden Quadrilateral, and what did it change?",
    a: "A 5,846 km highway network built from 2001 to 2012 linking Delhi, Mumbai, Chennai and Kolkata. Wider divided roads let trucks move faster, and factories grew along the route. A cess on petrol and diesel helped pay for it.",
    chain: [["5,846 km joining four big cities, 2001 to 2012", ["5,846", "5846", "four", "delhi", "2001", "2012"]], ["Old highways were narrow and slow", ["two lane", "narrow", "slow", "bullock", "under 40"]], ["Faster trucks and new factories along the route", ["truck", "factor", "faster", "grew", "route"]], ["Paid partly by a cess on fuel", ["cess", "petrol", "diesel", "tax", "paid"]]],
    mcq: { q: "Which four cities does the Golden Quadrilateral connect?", o: ["Delhi, Mumbai, Chennai and Kolkata", "Delhi, Mumbai, Bengaluru and Hyderabad", "Mumbai, Pune, Nagpur and Nashik", "Delhi, Jaipur, Agra and Lucknow"] },
    bring: "On a highway drive: “This is part of the Golden Quadrilateral. Nearly 6,000 km of road joining the four big cities.”",
    follow: "What would change in your business if goods reached Delhi a day faster?",
    deeper: "The project cost about 30,000 crore rupees, around half the first estimate. The Mumbai to Pune leg uses the expressway built by Maharashtra in 2002." },

  { id: "ie-mumbai-pune-expressway", type: "fact", domain: "geography", region: "india", title: "The Mumbai-Pune Expressway: India's first", value: 4, cue: "driving to Pune, Lonavala, or toll roads",
    emoji: "🚗", wiki: "Mumbai–Pune Expressway",
    fact: "The Mumbai-Pune Expressway, fully opened in 2002, was India's first expressway: a six-lane concrete road with no crossings, no shops and no two-wheelers. It is about 94.5 km long and cut the trip from four or five hours on the old highway to around two.",
    why: "It showed Indians what an access-controlled road was. Every expressway since, from Yamuna to Samruddhi, follows its model.",
    mech: "The old Mumbai-Pune highway crawled through towns and up the Khandala ghat behind trucks. The new road was built by a state company, MSRDC, and paid for by a toll. Access control, meaning entry only at a few points, is what makes it fast. No slow vehicles, no villages, no sudden crossings. The ghat section still has sharp bends and landslides, so a tunnel route, the Missing Link, has been built to bypass it.",
    models: ["bottlenecks", "first-principles"],
    q: "Why was the Mumbai-Pune Expressway so much faster than the old highway?",
    a: "It was India's first access-controlled road, opened fully in 2002. Entry only at a few points, no slow vehicles and no towns made it fast, cutting the trip to about two hours. A toll paid for it, and the ghat bottleneck is now bypassed by a tunnel link.",
    chain: [["India's first expressway, opened in 2002", ["2002", "first expressway", "94"]], ["Access control: few entries, no slow vehicles or towns", ["access", "entry", "no crossing", "two-wheeler", "no town", "slow vehicle"]], ["Trip time roughly halved to about two hours", ["two hours", "halved", "four or five", "cut"]], ["Toll-funded; the ghat is the remaining bottleneck", ["toll", "ghat", "khandala", "tunnel", "missing link"]]],
    mcq: { q: "What makes an expressway different from an ordinary highway?", o: ["Entry only at a few points, with no crossings or slow vehicles", "It is always free of toll", "It is built only of tar", "It allows higher trucks"] },
    bring: "On the way to Lonavala: “This was India's first expressway, in 2002. Before it, Pune was a five-hour drive.”",
    follow: "Why do you think it took India until 2002 to build its first expressway?",
    deeper: "It is one of the most expensive national routes to drive per kilometre because the toll is high. The old highway, NH-48, still runs alongside for two-wheelers and local traffic." },

  { id: "ie-petrol-price", type: "concept", domain: "economics", region: "india", title: "Why petrol costs what it does", value: 5, cue: "filling the tank, fuel prices, or why Mumbai pays more than Delhi",
    emoji: "⛽", wiki: "Indian Oil Corporation",
    fact: "Of the price you pay for a litre of petrol, roughly a third to a half is tax, depending on the year and the state. In Delhi in 2024 the fuel itself cost about 56 rupees, central excise about 20, state VAT about 15, and the dealer kept about 4, for a pump price near 95 rupees.",
    why: "When world oil prices fall and your petrol does not, this is where the money goes. It also explains why Mumbai is costlier than Delhi.",
    mech: "India imports nearly 90% of its crude oil, so the base price follows world oil and the rupee. On top sit two taxes. The centre charges excise duty, a fixed rupee amount per litre. Each state charges VAT, a percentage, and rates differ, so Maharashtra's petrol costs more than Delhi's. Since 2017 pumps have changed prices daily, in theory following world prices. Fuel taxes are easy to collect and hard to avoid, so both governments depend on them for lakhs of crore of revenue.",
    models: ["incentives", "second-order-thinking"],
    q: "What makes up the price of a litre of petrol in India?",
    a: "Base fuel cost, which follows world oil and the rupee because India imports about 90% of its crude. Then central excise, a fixed amount per litre, and state VAT, a percentage that differs by state. Taxes make up a third to a half, and governments depend on them.",
    chain: [["Base price follows imported crude and the rupee", ["import", "crude", "world oil", "rupee", "90"]], ["Central excise is a fixed amount per litre", ["excise", "centre", "fixed", "per litre", "20"]], ["State VAT is a percentage that varies by state", ["vat", "state", "percent", "maharashtra", "differ"]], ["Taxes are a third to half, and easy to collect", ["third", "half", "tax", "revenue", "collect"]]],
    mcq: { q: "Why does petrol cost more in Mumbai than in Delhi?", o: ["Maharashtra charges a higher state VAT", "Mumbai is farther from the sea", "Delhi refines its own oil", "Mumbai pumps add a city tax"] },
    bring: "At the petrol pump: “About 35 to 40 rupees of this litre is tax. The fuel itself is only about 55.”",
    follow: "If fuel tax was cut, what tax would you accept in its place?",
    deeper: "Petrol and diesel are kept outside GST, which is why states can set their own VAT. Petrol prices were freed from government control in 2010 and diesel in 2014." },

  { id: "ie-rupee-journey", type: "concept", domain: "economics", region: "india", title: "The rupee: from 4.76 a dollar to over 88", value: 5, cue: "foreign trips, the dollar rate, or why the rupee keeps falling",
    emoji: "💱", wiki: "Indian rupee",
    fact: "From 1947 to 1966 one US dollar cost 4.76 rupees, a rate fixed by the government. In June 1966 the rupee was devalued to 7.50. In 1991 it was devalued twice in two days. Since 1993 the market sets the rate, and by 2025 a dollar cost over 88 rupees.",
    why: "A falling rupee is not a scandal. It mostly reflects that prices have risen faster in India than in America for 70 years.",
    mech: "If prices in India rise 6% a year and in the US 2%, the rupee buys less each year compared with the dollar. Over decades this adds up. A fixed rate hides this until the gap becomes too wide, which forced the 1966 and 1991 devaluations. India also imports more than it exports, mainly oil and gold, so it sells rupees to buy dollars. Today the RBI lets the rate move but steps in to smooth sharp swings, called a managed float.",
    models: ["compounding", "first-principles"],
    q: "Why has the rupee fallen from 4.76 to over 88 per dollar?",
    a: "Mainly because Indian inflation has run higher than American inflation for decades, so each rupee buys less relative to a dollar. Fixed rates hid this until the 1966 and 1991 devaluations. India also imports more than it exports, and since 1993 the RBI lets the market set the rate with some smoothing.",
    chain: [["Fixed at 4.76 until 1966, then devalued in 1966 and 1991", ["4.76", "1966", "1991", "devalu", "fixed"]], ["Higher Indian inflation makes the rupee buy less over time", ["inflation", "prices rise", "faster", "6%", "buys less"]], ["Imports exceed exports, mainly oil and gold", ["import", "export", "oil", "gold", "deficit"]], ["Since 1993 a managed float set by the market", ["1993", "market", "managed float", "rbi", "smooth"]]],
    mcq: { q: "What is the main long-run reason the rupee has fallen against the dollar?", o: ["Indian inflation has been higher than American inflation for decades", "The government prints a new note every year", "America has more gold than India", "The rupee was never allowed to trade"] },
    bring: "When the dollar rate is in the news: “In 1966 a dollar was 4.76 rupees. The fall is mostly our higher inflation, year after year.”",
    follow: "If the rupee had stayed at 4.76, what would a foreign trip cost today?",
    deeper: "The 1966 devaluation followed two wars and a drought, and came under pressure from foreign lenders. The 1991 cuts were about 9% and 11%, on 1 and 3 July, during the foreign exchange crisis." },

  { id: "ie-oil-gold-imports", type: "concept", domain: "economics", region: "india", title: "Oil and gold: what India buys from the world", value: 4, cue: "the trade deficit, gold at weddings, or oil prices",
    emoji: "🛢️", wiki: "Jamnagar Refinery",
    fact: "India buys about 88% of the crude oil it uses from abroad, an import bill of roughly 100 billion dollars a year. Gold is usually the second biggest import. Indians buy around 800 tonnes of gold a year, almost all of it from outside, worth about 50 billion dollars.",
    why: "These two items explain most of India's trade gap. Every dollar they cost must be earned by exports or borrowed.",
    mech: "India has little oil under its ground but a huge and growing number of vehicles and factories. So oil must come in by ship, mostly from the Gulf, Russia and America. Gold is different: India mines almost none, but families buy it for weddings and as savings they can touch. Both are paid for in dollars. When oil or gold prices rise, India needs more dollars, which pushes the rupee down. The government has tried import duties on gold and schemes to turn household gold into paper, with limited effect.",
    models: ["opportunity-cost", "second-order-thinking"],
    q: "Why does India import so much oil and gold, and why does it matter?",
    a: "India has little oil of its own and mines almost no gold, yet it needs fuel for a growing economy and families buy around 800 tonnes of gold a year for weddings and savings. Both are paid in dollars, so they drive the trade gap and push the rupee down when prices rise.",
    chain: [["About 88% of crude oil is imported", ["88", "crude", "oil", "import", "100 billion"]], ["Around 800 tonnes of gold a year, almost none mined at home", ["800", "gold", "mine", "wedding", "saving"]], ["Both are paid for in dollars", ["dollar", "paid", "earn", "export"]], ["Higher prices need more dollars and weaken the rupee", ["rupee", "weak", "more dollars", "trade gap", "deficit"]]],
    mcq: { q: "Which two items account for most of India's import bill?", o: ["Crude oil and gold", "Cars and phones", "Wheat and rice", "Steel and cement"] },
    bring: "When gold prices come up: “India buys about 800 tonnes of gold a year and mines almost none. It is our second biggest import after oil.”",
    follow: "Is buying gold a saving for the family, or an import for the country? Can it be both?",
    deeper: "The Jamnagar refinery in Gujarat is the largest in the world. India imports crude, refines it, and is also a big exporter of petrol and diesel." },

  { id: "ie-surat-diamonds", type: "historical story", domain: "business", region: "india", title: "Surat polishes most of the world's diamonds", value: 5, cue: "diamonds, jewellery shops, or Gujarati business families", story: "ie-surat",
    emoji: "💎", wiki: "Surat Diamond Bourse",
    fact: "Around nine out of ten of the world's diamonds are cut and polished in Surat, Gujarat. Rough stones come from mines in Africa, Russia and Canada, are polished by lakhs of Surat workers, and go out to jewellers everywhere. In 2023 Surat opened the world's largest office building, a diamond exchange built for 65,000 people.",
    why: "A city with no diamond mines and no famous jewellery brand became the centre of the trade, by doing one step better and cheaper than anyone.",
    mech: "In the 1960s Jain traders from Palanpur in Gujarat went to Antwerp in Belgium, the world's diamond market. The big dealers there worked on large stones. The Indians took the small, cheap stones nobody wanted and sent them home to be cut by hand in Surat, where skilled labour cost very little. Small stones became worth cutting, and a huge new market opened. Over decades Surat moved up to bigger stones and better machines. Today the Gujarati families run much of Antwerp's trade too.",
    models: ["moat", "network-effects", "compounding"],
    q: "How did Surat come to polish most of the world's diamonds?",
    a: "Palanpuri Jain traders went to Antwerp in the 1960s and took the small stones big dealers ignored. They sent them to Surat, where skilled hand-cutting was very cheap, making small stones worth polishing. The trade grew over decades until Surat handled around 90% of the world's diamonds.",
    chain: [["Palanpuri Jains went to Antwerp in the 1960s", ["palanpur", "antwerp", "1960", "jain", "belgium"]], ["They took the small stones others ignored", ["small", "cheap stones", "nobody wanted", "ignored"]], ["Surat cut them cheaply with skilled hands", ["surat", "cheap", "skilled", "labour", "hand"]], ["Grew to about 90% of the world's diamonds", ["90", "nine out of ten", "most of the world", "largest"]]],
    mcq: { q: "Where are most of the world's diamonds cut and polished?", o: ["Surat, India", "Antwerp, Belgium", "Johannesburg, South Africa", "Tel Aviv, Israel"] },
    bring: "At a jewellery shop: “That diamond was almost certainly polished in Surat. Nine in ten of the world's stones are.”",
    follow: "Why do you think the big Antwerp dealers let the small stones go?",
    deeper: "The Surat Diamond Bourse covers about 6.6 million square feet, more than the Pentagon. Lab-grown diamonds, also a Surat speciality now, have begun to challenge the natural stone business." },

  { id: "ie-textile-towns", type: "concept", domain: "geography", region: "india", title: "Tirupur T-shirts, Surat saris, Ludhiana sweaters", value: 4, cue: "where clothes come from, cheap T-shirts, or a town known for one thing",
    emoji: "👕", wiki: "Tiruppur",
    fact: "Many Indian towns make one kind of cloth for the whole country. Tirupur in Tamil Nadu makes most of India's exported knitwear, such as T-shirts and vests. Surat weaves a large share of India's polyester cloth and saris. Ludhiana in Punjab makes woollens and hosiery. Bhiwandi near Mumbai runs lakhs of power looms.",
    why: "When a whole town does one job, each firm gets cheaper and better. That is why your T-shirt probably has a Tirupur label.",
    mech: "Once a few firms succeed in a place, suppliers of thread, dye and machines set up next door. Skilled workers move there. Buyers from abroad learn that one visit covers hundreds of factories. Each new firm makes the town more useful to the next. Economists call this a cluster. The cost is that one town carries one risk: a ban on dyeing units for polluting the river, or a fall in exports, hits everyone at once.",
    models: ["network-effects", "compounding", "margin-of-safety"],
    q: "Why do Indian towns specialise in one kind of cloth, and what is the risk?",
    a: "Once a few firms succeed, suppliers, skilled workers and buyers gather in the same town, making each new firm cheaper to run. This cluster effect gave Tirupur knitwear, Surat polyester and Ludhiana woollens. The risk is that one shock, like a pollution ban or export fall, hits the whole town.",
    chain: [["Towns specialise: Tirupur knitwear, Surat polyester, Ludhiana woollens", ["tirupur", "surat", "ludhiana", "knitwear", "polyester", "woollen", "special"]], ["Suppliers and skilled workers gather nearby", ["supplier", "thread", "dye", "skilled", "worker", "next door", "gather"]], ["Buyers come because one visit covers many factories", ["buyer", "one visit", "hundreds", "abroad"]], ["One shock hits the whole town", ["shock", "risk", "pollut", "ban", "hits everyone", "at once"]]],
    mcq: { q: "Tirupur in Tamil Nadu is known for which product?", o: ["Knitwear such as T-shirts", "Silk saris", "Leather shoes", "Brass lamps"] },
    bring: "Looking at a T-shirt label: “Tirupur. One town in Tamil Nadu makes most of India's T-shirt exports.”",
    follow: "What is one town you know that lives on a single trade?",
    deeper: "In 2011 the Madras High Court ordered Tirupur's dyeing units shut for polluting the Noyyal river. The town recovered by building plants that recycle almost all their water." },

  { id: "ie-one-product-towns", type: "concept", domain: "economics", region: "india", title: "Moradabad brass, Aligarh locks, Kanpur leather", value: 4, cue: "a product's home town, exports, or small workshops",
    emoji: "🔒", wiki: "Moradabad",
    fact: "India is full of towns tied to one product. Moradabad in Uttar Pradesh makes brass and metal ware that fills shops in Europe and America. Aligarh makes locks. Kanpur makes leather. Jaipur cuts coloured gemstones. Firozabad makes glass bangles. Each is a cluster of thousands of small workshops, not one big factory.",
    why: "These towns export thousands of crore of rupees a year from rooms the size of your kitchen. They show how Indian industry really looks.",
    mech: "A craft often started with a Mughal or princely court that wanted fine metal, leather or jewels. Skills passed from parent to child. Over generations the whole town learned the trade, so a buyer could place a large order and split it among hundreds of families. Traders handled the export, designs and raw material. Each workshop stayed small, so it stayed informal and cheap. The weakness is the same: little capital, old machines, and dependence on a few trader-exporters.",
    models: ["network-effects", "lindy-effect", "incentives"],
    q: "How did towns like Moradabad and Aligarh come to make one product, and how do they work?",
    a: "Many crafts began under a Mughal or princely court and passed from parent to child until the whole town knew the trade. Thousands of small workshops take parts of big orders, while traders handle export and raw material. Staying small keeps them cheap but short of capital.",
    chain: [["Many towns tied to one product, from brass to locks", ["moradabad", "aligarh", "kanpur", "brass", "lock", "leather", "one product"]], ["Crafts began under courts and passed down families", ["court", "mughal", "princely", "parent", "child", "generation", "passed"]], ["Thousands of small workshops share large orders", ["thousand", "workshop", "small", "split", "order", "families"]], ["Traders export; workshops stay cheap but short of capital", ["trader", "export", "capital", "old machine", "informal", "cheap"]]],
    mcq: { q: "Which town in Uttar Pradesh is famous for brass ware exports?", o: ["Moradabad", "Aligarh", "Kanpur", "Firozabad"] },
    bring: "When a brass lamp is admired: “That is probably from Moradabad. One town makes most of India's brass exports.”",
    follow: "Is it better for a town to be the best at one thing, or decent at many?",
    deeper: "Moradabad's brass trade is said to date to the Mughal era and exports several thousand crore rupees a year. Aligarh's lock industry has struggled against cheaper Chinese locks." },

  { id: "ie-kota-coaching", type: "historical story", domain: "business", region: "india", title: "Kota: the town that teaches for the IIT exam", value: 4, cue: "IIT coaching, entrance exams, or children sent away to study", story: "ie-kota",
    emoji: "📚", wiki: "Kota, Rajasthan",
    fact: "Kota, a small industrial city in Rajasthan, became India's coaching capital. At its peak around 2 lakh students a year moved there, aged 15 to 18, to prepare for the IIT and medical entrance exams. The coaching and hostel business was estimated at over 6,000 crore rupees a year.",
    why: "A whole city's economy, from hostels to tiffin services, is built on one exam. It shows how much Indian families will pay for a chance at a seat.",
    mech: "It began with one man. V. K. Bansal, an engineer at a Kota factory, was told in 1974 that he had muscular dystrophy and might not live long. He started teaching a few students at his dining table. When the factory shut in 1983, he taught full time. His students began getting into the IITs, and word spread. Other teachers left to start rival institutes. Hostels, mess halls and bookshops grew around them. Because the IIT seats are so few and the reward is so large, families pay lakhs for a small gain in odds.",
    models: ["incentives", "network-effects", "survivorship-bias"],
    q: "How did Kota become India's coaching capital?",
    a: "V. K. Bansal, a factory engineer with muscular dystrophy, started teaching a few students at his dining table and went full time when the factory shut in 1983. His students got into the IITs, rival institutes and hostels grew around them, and because IIT seats are so few, families pay lakhs for better odds.",
    chain: [["Bansal started teaching at his dining table", ["bansal", "dining table", "engineer", "muscular"]], ["Factory shut in 1983; he taught full time", ["1983", "factory", "full time", "shut"]], ["His students got into IITs and rivals and hostels followed", ["iit", "word spread", "rival", "institute", "hostel"]], ["Few seats and big rewards make families pay lakhs", ["few", "seats", "reward", "lakh", "odds", "pay"]]],
    mcq: { q: "What first made Kota famous for coaching?", o: ["V. K. Bansal's students began clearing the IIT entrance exam", "The government opened an IIT in Kota", "A film about Kota students became a hit", "Kota's schools were ranked best in India"] },
    bring: "When entrance exams come up: “Kota's whole economy runs on one exam. It began with one sick engineer teaching at his dining table.”",
    follow: "Would you send a 16-year-old to live alone in another city for two years for an exam?",
    deeper: "Student numbers fell by a third or more after 2023 amid concern over stress, and reports of student suicides, and have begun to recover. Many top teachers in Kota are themselves former Kota students." },

  { id: "ie-wedding-industry", type: "fact", domain: "business", region: "india", title: "The wedding industry: 1 crore weddings a year", value: 3, cue: "wedding season, gold buying, or a friend's big-fat wedding",
    emoji: "💍", wiki: "Weddings in India",
    fact: "India holds roughly 80 lakh to 1 crore weddings a year. A 2024 estimate put total wedding spending at about 130 billion dollars, around 10 lakh crore rupees, which is about twice the US figure. That makes weddings the second largest thing Indians spend on, after food and groceries.",
    why: "Jewellers, caterers, hotels, tailors and bands plan their whole year around the wedding months. Gold imports rise and fall with them.",
    mech: "An Indian wedding is not one event but several, often over days, with hundreds of guests. Gold is both gift and savings. Families save for years and spend in a few weeks, and much of the money moves in cash. Because dates follow the calendar of auspicious days, demand bunches into a few months, so hotels and bands charge peak prices. Studies estimate the average spend at around 12 lakh rupees, several times the family's yearly income for many.",
    models: ["social-proof", "commitment-consistency"],
    q: "Why is the wedding industry so big in India, and what does it do to the economy?",
    a: "Around 1 crore weddings a year, each with several events, hundreds of guests and gold as gift and savings, add up to about 10 lakh crore rupees, the second largest spend after food. Dates bunch in auspicious months, so jewellers, hotels and bands charge peak prices then.",
    chain: [["About 1 crore weddings and 10 lakh crore rupees a year", ["1 crore", "80 lakh", "10 lakh crore", "130 billion", "second largest"]], ["Several events, hundreds of guests and gold", ["event", "guest", "gold", "days", "hundreds"]], ["Dates bunch into auspicious months", ["auspicious", "month", "bunch", "season", "calendar"]], ["Peak prices for hotels, jewellers and bands", ["peak", "price", "hotel", "jeweller", "band", "caterer"]]],
    mcq: { q: "After food and groceries, what is often estimated to be the second largest spending category in India?", o: ["Weddings", "Cars", "Smartphones", "Foreign travel"] },
    bring: "In wedding season: “Indians hold about a crore weddings a year. Spending is about double America's, on a far smaller income.”",
    follow: "What is one wedding expense you think nobody would miss?",
    deeper: "These numbers come from a Jefferies report in 2024 and are estimates. The fixed auspicious dates mean a single November day can see lakhs of weddings across the country." },

  { id: "ie-jan-dhan-dbt", type: "concept", domain: "economics", region: "india", title: "Jan Dhan and money sent straight to the account", value: 5, cue: "bank accounts for the poor, subsidies, or leakage in welfare",
    emoji: "🏦", wiki: "Pradhan Mantri Jan Dhan Yojana",
    fact: "The Jan Dhan scheme, launched in August 2014, opened zero-balance bank accounts for people who had none. About 1.5 crore accounts were opened on the first day. By 2025 there were over 56 crore accounts holding about 2.7 lakh crore rupees. Government payments now go straight into these accounts, called direct benefit transfer.",
    why: "Before, a pension or gas subsidy passed through many hands and some of it vanished. A direct transfer skips the hands.",
    mech: "Three things were joined: a Jan Dhan account, an Aadhaar number and a mobile phone. Aadhaar proves the person exists and is unique, so the same person cannot collect twice. The account receives the money. The phone sends a message confirming it. Together they remove fake names and middlemen. The government says this has saved lakhs of crore in payments that would have gone to ghost accounts. Critics note that some real people were also cut off when their fingerprints or records failed to match.",
    models: ["incentives", "first-principles", "second-order-thinking"],
    q: "How do Jan Dhan accounts and direct benefit transfer change welfare payments?",
    a: "Over 56 crore zero-balance accounts were opened from 2014. Linked with Aadhaar and a mobile phone, they let the government pay pensions and subsidies directly, removing fake names and middlemen. The state says it saved lakhs of crore, though some genuine people were cut off by failed matches.",
    chain: [["Zero-balance accounts from 2014, now over 56 crore", ["2014", "56 crore", "zero", "account", "1.5 crore"]], ["Linked to Aadhaar and a mobile phone", ["aadhaar", "mobile", "phone", "linked", "unique"]], ["Money goes direct, skipping middlemen and fake names", ["direct", "middle", "fake", "ghost", "skip", "hands"]], ["Big savings claimed, but some real people excluded", ["save", "lakhs of crore", "cut off", "exclu", "fail", "critic"]]],
    mcq: { q: "What does direct benefit transfer mean?", o: ["Government money is paid straight into the person's bank account", "Shops give goods free and bill the government", "Officials hand out cash at the village office", "Banks lend to the poor at zero interest"] },
    bring: "When welfare leakage comes up: “Jan Dhan opened 1.5 crore accounts in one day. Now the money skips the middlemen and lands in the account.”",
    follow: "What do you lose if a system that stops fraud also stops some honest people?",
    deeper: "Jan Dhan set a Guinness record for the most accounts opened in a week, about 1.8 crore. In 2024-25 the government moved about 6.8 lakh crore rupees through direct transfers across hundreds of schemes." },

  { id: "ie-gst-2017", type: "concept", domain: "economics", region: "india", title: "GST: one tax to replace seventeen", value: 5, cue: "the GST on your bill, prices, or how states earn money",
    emoji: "🧾", wiki: "Goods and Services Tax (India)",
    fact: "The Goods and Services Tax began at midnight on 1 July 2017. It replaced around 17 central and state taxes, including excise, service tax, VAT and octroi, with one tax on each sale. In September 2025 the main rates were cut to two, 5% and 18%, with a 40% rate for a few goods such as tobacco and luxury cars.",
    why: "Before GST a truck from Mumbai to Delhi stopped at every state border to pay tax. Now the tax follows the goods, not the border.",
    mech: "GST is a tax on value added at each step. A mill pays GST on cloth, a tailor on the shirt, a shop on the sale, but each gets credit for the tax already paid before. So the tax is not charged on tax. The centre and states share the money, and a GST Council of all finance ministers sets the rates together. Because every seller's credit depends on the buyer's invoice, firms push each other to bill properly. Monthly collections grew to around 2 lakh crore rupees by 2025.",
    models: ["incentives", "first-principles", "bottlenecks"],
    q: "What did GST replace, and how does it work?",
    a: "It replaced about 17 taxes from 1 July 2017 with one tax on value added at each step. Each seller gets credit for tax already paid, so there is no tax on tax, and the border checkposts went. The centre and states share it, a council sets rates, and in 2025 the rates were cut to mainly 5% and 18%.",
    chain: [["One tax replaced about 17 taxes from 1 July 2017", ["2017", "17", "seventeen", "replace", "one tax", "octroi"]], ["Tax on value added with credit for tax already paid", ["value added", "credit", "already paid", "tax on tax"]], ["No more state border checkposts", ["border", "checkpost", "truck", "stop"]], ["Shared by centre and states; rates now mainly 5% and 18%", ["council", "share", "5%", "18%", "2025", "centre and states"]]],
    mcq: { q: "When did GST start in India?", o: ["1 July 2017", "1 April 2010", "15 August 2014", "8 November 2016"] },
    bring: "Looking at a restaurant bill: “Before 2017 this would have had service tax and VAT. GST replaced 17 taxes with one.”",
    follow: "Do you think two rates are enough for a country that sells both salt and sports cars?",
    deeper: "Petrol, diesel and alcohol stay outside GST, so states still tax them on their own. The GST Council needs a three-fourths vote, and the centre alone holds one third of the votes." },

  { id: "ie-demonetisation-2016", type: "event", domain: "economics", region: "india", title: "8 November 2016: the night the notes stopped", value: 5, cue: "cash, bank queues, or the 500 and 1000 rupee notes",
    emoji: "💵", wiki: "2016 Indian banknote demonetisation",
    fact: "At 8 pm on 8 November 2016, the government announced that 500 and 1,000 rupee notes would stop being legal from midnight. These notes were about 86% of all cash by value, around 15.4 lakh crore rupees. People had until the end of December to deposit them. The RBI later reported that about 99.3% of the notes came back.",
    why: "For weeks India queued at banks and ATMs. It is the largest sudden removal of cash any big country has tried.",
    mech: "The stated aims were to catch untaxed cash, fake notes and money used for crime, and to push people toward digital payment. The idea was that hidden cash would not be returned and would die. But almost all of it was deposited, so little was destroyed. Printing new 500 and 2,000 notes took months, and ATMs had to be adjusted, so cash was short. Small businesses and daily wage workers, who ran on cash, were hit hardest. Digital payments did grow sharply from then on. Economists still debate the overall effect on growth.",
    models: ["second-order-thinking", "incentives", "bottlenecks"],
    q: "What happened on 8 November 2016, and what did the data later show?",
    a: "At 8 pm the government cancelled 500 and 1,000 rupee notes, about 86% of cash, from midnight. The aim was to catch untaxed and fake cash, but the RBI found 99.3% of notes returned. Cash ran short for weeks, hurting small cash-based businesses, while digital payments grew.",
    chain: [["500 and 1,000 notes cancelled at 8 pm, about 86% of cash", ["8 november", "8 pm", "86", "500", "1,000", "1000", "midnight", "cancel"]], ["Aim: catch untaxed cash, fake notes and push digital", ["untaxed", "black", "fake", "digital", "aim"]], ["About 99.3% of notes returned", ["99.3", "returned", "came back", "deposit"]], ["Cash shortage hit small and informal business; digital grew", ["shortage", "short", "queue", "small business", "daily wage", "cash-based", "grew"]]],
    mcq: { q: "According to the RBI, about what share of the cancelled notes came back to banks?", o: ["About 99%", "About 50%", "About 75%", "About 25%"] },
    bring: "When cash shortages come up: “In November 2016, 86% of India's cash stopped working at midnight. In the end 99.3% of it came back to the banks.”",
    follow: "Where were you on the night of 8 November 2016, and what did you do the next morning?",
    deeper: "The new 2,000 rupee note introduced that month was itself withdrawn in 2023. India had also demonetised high-value notes in 1946 and 1978, but those notes were rarely used by ordinary people." },

  { id: "ie-budget-day", type: "fact", domain: "history", region: "india", title: "Budget day: halwa, a locked basement and 11 am", value: 3, cue: "the Union Budget, 1 February, or tax changes",
    emoji: "🍮", wiki: "Union budget of India",
    fact: "India's Union Budget is presented on 1 February at 11 am. Until 1999 it was read at 5 pm, a British habit so that London could hear it in the morning. Until 2017 it was read at the end of February. Before the speech, a halwa ceremony starts the printing, and the staff then stay locked in the North Block basement until it is over.",
    why: "The budget decides your tax, the price of a cylinder and the money for roads. The small rituals around it show how seriously secrecy is taken.",
    mech: "If a tax change leaked early, traders could buy or sell to profit from it. So the officers and printers who prepare the papers are cut off from phones and families for days. The 5 pm time was changed by finance minister Yashwant Sinha in 1999 so Indian markets, not London, got the news first. The date was moved to 1 February in 2017 by Arun Jaitley so that spending could start on 1 April, the first day of the financial year, instead of months later. The same year the separate Railway Budget, read since 1924, was merged into the main one.",
    models: ["incentives", "second-order-thinking"],
    q: "Why is the budget read at 11 am on 1 February, and why the halwa and the lock-in?",
    a: "The 5 pm time, kept so London could listen, was changed to 11 am in 1999. The date moved to 1 February in 2017 so spending could begin on 1 April. The halwa ceremony starts printing, after which staff stay locked in the North Block basement so no tax change leaks.",
    chain: [["Read at 5 pm until 1999 for London's convenience", ["5 pm", "london", "1999", "british"]], ["Moved to 1 February in 2017 so spending can start on 1 April", ["1 february", "2017", "1 april", "financial year", "spending"]], ["Halwa ceremony starts the printing", ["halwa", "printing", "ceremony"]], ["Staff locked in the basement to prevent leaks", ["lock", "basement", "north block", "leak", "secre"]]],
    mcq: { q: "Why was the budget speech read at 5 pm until 1999?", o: ["So it could be heard in London in the morning", "Because Parliament met only in the evening", "To let markets close first in Mumbai", "Because of a rule in the Constitution"] },
    bring: "On 1 February: “The budget used to be read at 5 pm so London could hear it over breakfast. We changed that only in 1999.”",
    follow: "Which single line in a budget speech would change your own year the most?",
    deeper: "The Economic Survey, a report on the state of the economy, is released a day or two before the budget. Since 2021 the budget has been paperless, read from a tablet, though the halwa is still served." },

  { id: "ie-census-2027", type: "fact", domain: "history", region: "india", title: "The census that waited: 2011 to 2027", value: 4, cue: "population figures, the delayed census, or the caste count",
    emoji: "📋", wiki: "Census of India",
    fact: "India has counted its people every ten years since 1881, through wars and the Partition. The 2011 census counted 121 crore people. The 2021 count was postponed because of Covid and has become Census 2027, with house-listing from April 2026 and the head count in February 2027. It will be the first full census since 1931 to record every person's caste.",
    why: "Almost every number you hear about India, from how many people a ration shop serves to how many seats a state gets, still rests on a count from 2011.",
    mech: "A census is the only count that reaches every household. Surveys sample a few thousand homes and scale up, but the scale itself depends on the last census. So for 16 years, estimates of the poor, the urban, the migrant and the eligible have drifted. Welfare limits set from 2011 numbers, for example, leave out people born since. The new census will be digital, filled on phones, and will ask about caste for the first time since British times, a change decided in 2025.",
    models: ["map-vs-territory", "bayesian-thinking"],
    q: "Why does the delayed census matter, and what is new about the next one?",
    a: "Every ten-yearly count since 1881 happened on time until 2021, which was postponed by Covid. All surveys and welfare limits still rest on the 2011 count of 121 crore, so estimates have drifted. Census 2027 will be digital and will record caste for the first time since 1931.",
    chain: [["Counted every ten years since 1881; 2011 found 121 crore", ["1881", "ten years", "121 crore", "2011"]], ["The 2021 census was postponed by Covid", ["2021", "postpone", "covid", "delay"]], ["Surveys and welfare limits rest on the old count", ["survey", "welfare", "rest", "drift", "estimate", "ration"]], ["Census 2027 will be digital and count caste", ["2027", "digital", "caste", "phone", "1931"]]],
    mcq: { q: "Why was India's 2021 census not held on time?", o: ["It was postponed because of the Covid pandemic", "Parliament voted to stop counting", "The 2011 data was found to be enough", "A court order stopped it"] },
    bring: "When a population figure is quoted: “That is probably still based on 2011. We have not had a census since.”",
    follow: "What is one thing about your own neighbourhood that has changed since 2011?",
    deeper: "The first full census of India was in 1872 and the first synchronised one in 1881. The 2011 census needed about 27 lakh enumerators, mostly school teachers." },

  { id: "ie-million-cities", type: "fact", domain: "geography", region: "india", title: "India's 53 million-plus cities", value: 3, cue: "urbanisation, small cities growing, or where jobs are",
    emoji: "🏙️", wiki: "List of million-plus urban agglomerations in India",
    fact: "The 2011 census counted 53 urban areas with over 10 lakh people, up from 35 in 2001. Three were above 1 crore: Mumbai, Delhi and Kolkata. About 31% of Indians lived in towns and cities, a share that is believed to have passed 35% since.",
    why: "India is still mostly rural by the official count, but its cities hold most of the economy. The next crore of urban Indians will mostly land in cities you rarely hear of.",
    mech: "Farming cannot absorb more workers, so people move to where the jobs are. Big cities are costly, so growth spills into cities like Surat, Indore, Coimbatore and Lucknow, each already far bigger than many European capitals. Indian definitions of urban are strict, requiring most men to work outside farming, so many large villages are not counted as towns. Other counts, using satellite images of built-up land, suggest India is far more urban than 31%.",
    models: ["map-vs-territory", "network-effects"],
    q: "How urban is India, and where is the growth happening?",
    a: "The 2011 census found 53 cities over 10 lakh and 31% of people urban, though strict definitions undercount towns. People leave farming for jobs, and since big cities are costly, growth spills into second-rank cities like Surat, Indore and Lucknow.",
    chain: [["53 million-plus cities in 2011, three over 1 crore", ["53", "35", "1 crore", "mumbai", "delhi", "kolkata", "10 lakh"]], ["About 31% officially urban, likely more", ["31", "35", "urban", "rural", "share"]], ["Growth spills into second-rank cities", ["surat", "indore", "coimbatore", "lucknow", "spill", "second", "smaller"]], ["Strict definitions undercount towns", ["definition", "strict", "undercount", "satellite", "village"]]],
    mcq: { q: "Which three Indian urban areas had over 1 crore people in the 2011 census?", o: ["Mumbai, Delhi and Kolkata", "Mumbai, Bengaluru and Hyderabad", "Delhi, Chennai and Pune", "Kolkata, Ahmedabad and Surat"] },
    bring: "When someone says India is a land of villages: “By the census, yes, 69% rural. But we had 53 cities over ten lakh people, back in 2011.”",
    follow: "Which smaller city do you think will be the next Mumbai-sized place?",
    deeper: "A village is counted as a town only if it has over 5,000 people, at least 400 per square km, and three quarters of its working men outside farming. Many places fail the last test despite looking like towns." },

  { id: "ie-tea-darjeeling", type: "fact", domain: "geography", region: "india", title: "Assam grows half of India's tea; Darjeeling guards a name", value: 4, cue: "your morning chai, tea estates, or fake branded goods",
    emoji: "🍵", wiki: "Darjeeling tea",
    fact: "India makes about 1,300 million kg of tea a year, second only to China, and drinks most of it at home. Assam alone grows about half. Darjeeling grows only around 6 million kg, yet far more tea is sold as Darjeeling worldwide than the hills can produce. In 2004 Darjeeling tea became the first Indian product to get a Geographical Indication tag.",
    why: "Your chai is almost certainly Assam. The small Darjeeling crop is valuable only as long as the name is protected.",
    mech: "Assam's hot, wet plains grow a strong, dark tea that stands up to milk and sugar, so it fills India's cups. Darjeeling's cool hills grow a light, scented tea that sells for many times the price abroad. When a name sells, others copy it, so blends with little Darjeeling were sold under the name. A GI tag is a legal rule that only tea grown in a named place can use the name. Darjeeling's growers used it to force the European Union and others to protect the name.",
    models: ["moat", "incentives"],
    q: "Why does Assam dominate Indian tea, and why did Darjeeling need a GI tag?",
    a: "Assam's hot wet plains grow strong tea that suits milky chai and makes up half of India's 1,300 million kg. Darjeeling grows a small, costly crop, so others sold blends under its name. The GI tag of 2004 legally limits the name to tea from Darjeeling.",
    chain: [["India makes about 1,300 million kg, Assam about half", ["1,300", "1300", "1,285", "half", "assam", "second"]], ["Assam tea is strong and suits milky chai", ["strong", "dark", "milk", "chai", "plains"]], ["Darjeeling's small costly crop was copied in name", ["small", "copied", "copy", "fake", "blend", "more tea is sold", "far more"]], ["GI tag of 2004 protects the name", ["gi", "geographical indication", "2004", "protect", "legal"]]],
    mcq: { q: "Which Indian product was the first to get a Geographical Indication tag?", o: ["Darjeeling tea", "Alphonso mango", "Kolhapuri chappal", "Banarasi sari"] },
    bring: "Over a cup of chai: “This is Assam. Darjeeling grows so little that most ‘Darjeeling’ sold in the world cannot be real.”",
    follow: "What other Indian product name do you think is copied the most?",
    deeper: "India drinks about 80% of the tea it grows, and tea estates employ over 10 lakh workers. The Darjeeling GI was later registered in the European Union too, in 2011." },

  { id: "ie-spices-today", type: "fact", domain: "economics", region: "india", title: "India still runs the spice trade", value: 3, cue: "the masala box, Kerala pepper, or Guntur chilli",
    emoji: "🌶️", wiki: "Spices Board of India",
    fact: "India is the world's largest producer, user and exporter of spices. In 2024-25 it exported about 1.8 million tonnes worth around 4.5 billion dollars. Chilli, cumin, turmeric and mint products lead the list, with Guntur in Andhra Pradesh running the largest chilli market in Asia.",
    why: "Europeans sailed round Africa for Indian pepper 500 years ago. The trade never left; it just changed from pepper to chilli and turmeric powders.",
    mech: "Spices need specific soils and climates, and India has many: wet Kerala for pepper and cardamom, dry Gujarat and Rajasthan for cumin, Andhra and Telangana for chilli. Lakhs of small farmers grow them, and old market towns like Guntur and Unjha sort and price the crop. Export now leans toward processed goods, such as curry powders, oils and oleoresins, which earn more per kilo than raw spice. Quality rules abroad, on pesticide and colour, decide which lots can be shipped.",
    models: ["lindy-effect", "network-effects"],
    q: "Why does India still lead the world spice trade?",
    a: "India's many climates grow pepper in Kerala, cumin in Gujarat and chilli in Andhra, farmed by lakhs of small growers and sorted in old market towns like Guntur. Exports of about 4.5 billion dollars a year now lean toward processed powders and oils, which earn more per kilo.",
    chain: [["Largest producer, user and exporter, about 4.5 billion dollars", ["largest", "4.5 billion", "1.8 million", "export"]], ["Many climates suit many spices", ["climate", "soil", "kerala", "gujarat", "andhra", "pepper", "cumin"]], ["Small farmers and old market towns like Guntur", ["farmer", "guntur", "unjha", "market town", "sort"]], ["Processed powders and oils earn more per kilo", ["process", "powder", "oil", "oleoresin", "per kilo", "more"]]],
    mcq: { q: "Which town hosts the largest chilli market in Asia?", o: ["Guntur, Andhra Pradesh", "Kochi, Kerala", "Unjha, Gujarat", "Nagpur, Maharashtra"] },
    bring: "Looking at the masala box: “India still grows, eats and exports more spices than any country. About 4.5 billion dollars a year goes abroad.”",
    follow: "Which spice in your kitchen do you think travelled the farthest to get there?",
    deeper: "Mint products, especially menthol from Uttar Pradesh, are among the top export earners, though few think of mint as a spice. The Spices Board aims for exports of 10 billion dollars by 2030." },

  { id: "ie-fish-economy", type: "fact", domain: "geography", region: "india", title: "India's fish mostly come from ponds, not the sea", value: 3, cue: "fish prices, Sassoon Dock, or the Koli fishermen",
    emoji: "🐟", wiki: "Fishing in India",
    fact: "India is the world's second largest fish producer after China, with around 18 million tonnes a year. About three quarters of that is inland fish, from ponds, rivers and reservoirs, not the sea. Andhra Pradesh, with its vast fish and shrimp ponds, produces more fish than any coastal state's boats.",
    why: "You might picture fishing boats. Most Indian fish today is farmed in fresh water, and shrimp from ponds is one of India's biggest farm exports.",
    mech: "The sea catch has stopped growing because the near coast is fished out and deep-sea boats are costly. Pond farming can grow as long as there is land and water. Andhra's farmers turned rice paddies into fish and shrimp ponds, which earn far more per acre. Shrimp is sold to America and China for dollars. Around 3 crore people depend on fishing and fish farming, many of them women who sort, dry and sell the catch.",
    models: ["second-order-thinking", "opportunity-cost"],
    q: "Where does most of India's fish come from, and why?",
    a: "About three quarters of India's roughly 18 million tonnes comes from inland ponds and rivers, because the sea catch has stopped growing while pond farming can expand. Andhra farmers turned paddies into fish and shrimp ponds, and shrimp is now a big dollar export.",
    chain: [["Second largest producer, about 18 million tonnes", ["second", "18 million", "17", "china", "largest"]], ["About three quarters is inland, not sea", ["three quarter", "inland", "pond", "river", "fresh water", "not the sea"]], ["Sea catch has stopped growing; ponds can expand", ["sea catch", "fished out", "stopped growing", "expand", "deep-sea"]], ["Andhra ponds and shrimp exports", ["andhra", "shrimp", "export", "paddies", "dollar"]]],
    mcq: { q: "Where does most of India's fish production come from?", o: ["Inland ponds, rivers and reservoirs", "Deep-sea trawlers in the Arabian Sea", "Imports from Bangladesh", "The Andaman Islands"] },
    bring: "At the fish market: “Three quarters of India's fish now comes from ponds, not boats. Andhra out-produces every coastal fleet.”",
    follow: "Does it matter to you whether a fish was caught or farmed?",
    deeper: "Frozen shrimp earns India several billion dollars a year, mostly from the United States. Marine fishing is banned along the coasts for about two months each monsoon to let fish breed." },

  { id: "ie-unicorns", type: "business concept", domain: "business", region: "india", title: "Unicorns: India's startup wave, counted carefully", value: 4, cue: "startups, funding news, or a friend joining a new app company",
    emoji: "🦄", wiki: "List of unicorn startup companies",
    fact: "A unicorn is a private startup valued at over 1 billion dollars. India had a handful in 2015. In 2021 alone around 40 Indian startups crossed the mark, the most ever in one year. By 2025 counts ranged from about 70 to over 110, depending on who counts and whether companies that fell in value or went public are included.",
    why: "The food, taxi, payment and shopping apps on your phone are mostly these companies. Their rise and cooling also show how global money moves.",
    mech: "A valuation is a price paid by the last investor for a small slice, multiplied over the whole company. In 2020 and 2021 interest rates in America were near zero, so investors hunted for growth anywhere and paid high prices for Indian startups. When rates rose in 2022, the money slowed sharply, a period called the funding winter. Many unicorns cut staff and some lost their title. A few, like Zomato and Nykaa, listed on the stock market, where a public price replaced the private guess.",
    models: ["mr-market", "survivorship-bias", "incentives"],
    q: "What is a unicorn, and why did India get so many in 2021 and fewer after?",
    a: "A private startup valued above 1 billion dollars, based on the price the last investor paid. Near-zero interest rates in 2020 and 2021 sent global money hunting for growth, creating around 40 Indian unicorns in one year. When rates rose in 2022, funding froze, staff were cut and some lost the title.",
    chain: [["A private startup valued over 1 billion dollars", ["1 billion", "billion dollars", "private", "valued"]], ["Valuation is the last investor's price scaled up", ["last investor", "slice", "multiplied", "price paid", "guess"]], ["Cheap global money created about 40 in 2021", ["2021", "40", "interest rate", "zero", "cheap", "global money"]], ["Rates rose in 2022 and funding froze", ["2022", "winter", "froze", "slowed", "cut staff", "rose"]]],
    mcq: { q: "What does the word unicorn mean in business?", o: ["A private startup valued at over 1 billion dollars", "A company with over 1 crore users", "A startup that is profitable in its first year", "A company owned by one person"] },
    bring: "When a startup's valuation is in the news: “That number is what the last investor paid for a small slice, times the whole. It is a guess, not a sale.”",
    follow: "Which app on your phone do you think is actually making money?",
    deeper: "Counts differ because some lists drop companies that went public or fell below 1 billion dollars. The number of unicorns tells you more about investor mood than about how many good companies exist." },

  { id: "ie-demat-boom", type: "fact", domain: "business", region: "india", title: "From 4 crore to 21 crore demat accounts", value: 4, cue: "share market talk, SIPs, or a friend's first stock",
    emoji: "📈", wiki: "National Stock Exchange of India",
    fact: "A demat account holds shares in electronic form. In March 2020 India had about 4 crore of them. By the end of 2025 there were over 21 crore. Most of the new ones were opened on phone apps, by first-time investors in their twenties and thirties, many from small towns.",
    why: "For a century the share market was a Dalal Street affair. In five years it became something tens of crores of ordinary Indians take part in.",
    mech: "Three things came together. The 2020 lockdown left people at home with time and a phone. New apps let anyone open an account in minutes with Aadhaar and UPI, often for free. And share prices rose strongly from the 2020 low, so early gains drew friends in. Monthly SIPs into mutual funds also moved household savings from gold and deposits into shares. Many accounts are small or idle, and the number of accounts is higher than the number of people, since one person can hold several.",
    models: ["social-proof", "network-effects", "mr-market"],
    q: "Why did India's demat accounts grow from 4 crore to over 21 crore in five years?",
    a: "The 2020 lockdown gave people time and a phone, new apps opened accounts in minutes using Aadhaar and UPI, and rising prices drew friends in. SIPs moved savings from gold and deposits into shares. Many accounts are small, and one person may hold several.",
    chain: [["About 4 crore accounts in 2020, over 21 crore by 2025", ["4 crore", "21 crore", "2020", "2025"]], ["Lockdown time plus phone apps with Aadhaar and UPI", ["lockdown", "app", "phone", "aadhaar", "upi", "minutes"]], ["Rising prices and friends' gains drew people in", ["rising", "rose", "gain", "friend", "drew"]], ["Many accounts are small, idle or duplicates", ["small", "idle", "several", "duplicate", "higher than the number"]]],
    mcq: { q: "Roughly how many demat accounts did India have by the end of 2025?", o: ["Over 21 crore", "About 4 crore", "About 1 crore", "About 50 crore"] },
    bring: "When a friend starts trading: “India went from 4 crore demat accounts to 21 crore in five years. You are part of a stampede.”",
    follow: "Do you know anyone who opened a demat account in 2021 and never used it again?",
    deeper: "The two depositories are NSDL and CDSL. CDSL, which serves most of the new app-based investors, held about 17 crore of the 21 crore accounts." }
  ]));

  MV.STORIES.push(
  { id: "ie-grid", assetId: "ie-blackout-2012", title: "The Day Half of India Went Dark",
    hook: "On a hot July morning in 2012, the lights went out for 62 crore people, more than the whole of Europe.",
    setting: "Northern India, 30 July 2012. The monsoon is weak and late. Fields are dry, farmers are running pumps, and cities are running fans around the clock.",
    character: "The grid operators in Delhi watching their screens, and the hundreds of millions of people who had no idea their power came from one shared machine.",
    conflict: "Several northern states were drawing far more power than their share. Operators asked them to cut back. Nobody wanted to be the state that switched off its farmers.",
    surprise: "At about 2:30 in the morning a key 400 kV line near Gwalior tripped. Its load jumped onto other lines, which tripped one after another like dominoes. In minutes the northern grid was dark.",
    turning: "Power was restored by that evening. Then on 31 July it happened again, and this time the eastern and north-eastern grids collapsed too. About 62 crore people, nearly a tenth of the world, had no power. Trains stopped between stations and miners were trapped underground in West Bengal.",
    payoff: "Nobody could blame one plant or one storm. The cause was many states each taking a little too much from a shared pool. Afterwards penalties for over-drawing were made stiffer, and in December 2013 the southern grid was joined to the rest to make one national grid.",
    meaning: "A shared system fails when everyone takes a little more than their share. The lights in Punjab and the lights in Assam were always the same lights.",
    extra: ["Mumbai stayed lit because its islanding system cut the city off from the grid the moment the grid became unstable.", "It remains the largest blackout in history by number of people affected.", "The southern grid was linked on 31 December 2013 through a 765 kV line between Raichur in Karnataka and Solapur in Maharashtra."],
    facts: [["2012", "july"], ["62 crore", "620 million", "tenth of the world"], ["gwalior", "400 kv", "line"], ["domino", "tripped one after another", "cascad"], ["over", "more than their share", "drawing far more"], ["2013", "national grid", "one grid"], ["monsoon", "pumps", "fans"]],
    vocab: ["grid", "cascade", "over-draw"] },

  { id: "ie-surat", assetId: "ie-surat-diamonds", title: "The Stones Nobody Wanted",
    hook: "A few traders from a small Gujarat town went to Belgium in the 1960s to buy the diamonds nobody else would touch.",
    setting: "Antwerp, Belgium, in the 1960s. For centuries this city has been where the world's rough diamonds are bought and sold, mostly by old Jewish dealing families.",
    character: "Jain traders from Palanpur in north Gujarat, arriving with little capital, and the hand-cutters of Surat, hundreds of kilometres from any diamond mine.",
    conflict: "The Antwerp dealers worked on large, valuable stones. The small, flawed rough stones were hardly worth the cost of cutting in Europe, where skilled labour was expensive.",
    surprise: "The Palanpuris bought exactly those stones. They sent them to Surat, where a skilled cutter could polish a tiny stone for a fraction of the European wage. Suddenly the small stones were worth cutting.",
    turning: "A whole new market opened: cheap diamond jewellery for ordinary buyers in America and Europe, set with small Indian-cut stones. Surat's workshops multiplied, and over the decades they moved up to larger stones and machine cutting.",
    payoff: "Today about nine out of ten of the world's diamonds pass through Surat. The Gujarati families, from a few hundred in Antwerp, came to run much of its trade. In 2023 Surat opened the world's largest office building, a bourse built for 65,000 diamond workers and traders.",
    meaning: "The best opening is often the work the strong players consider beneath them. Do that work better and cheaper, and the market comes to you.",
    extra: ["Many Surat cutters came from farming families in Saurashtra, and the trade pulled lakhs of them into the city.", "Surat is now also a centre for lab-grown diamonds, which threaten the natural stone trade it built.", "The Surat Diamond Bourse covers about 6.6 million square feet, larger than the Pentagon."],
    facts: [["antwerp", "belgium"], ["palanpur"], ["1960"], ["small", "nobody wanted", "beneath them", "flawed"], ["surat"], ["nine out of ten", "90"], ["2023", "largest office", "bourse"]],
    vocab: ["rough", "polish", "bourse"] },

  { id: "ie-kota", assetId: "ie-kota-coaching", title: "Eight Students at a Dining Table",
    hook: "A factory engineer was told he had a few years to live. What he did with them turned a small town into India's exam capital.",
    setting: "Kota, Rajasthan, in the 1970s and 1980s. A dusty industrial town on the Chambal river, known for its factories, not its schools.",
    character: "Vinod Kumar Bansal, a mechanical engineer at the JK Synthetics factory, and the local children who came to him for help with maths.",
    conflict: "In 1974 doctors told Bansal he had muscular dystrophy, a disease that slowly weakens the muscles. He would lose the use of his body and was not expected to live long.",
    surprise: "He did not stop working. He began teaching a handful of students at his dining table in the evenings. When the factory shut in 1983, teaching became his full-time job, with eight students.",
    turning: "His students started clearing the IIT entrance exam, one of the hardest tests in the world. Word spread from town to town. Families began sending their children to Kota to study under Bansal sir. Teachers who trained with him left to start their own institutes.",
    payoff: "Kota grew into a city of coaching towers, hostels and tiffin services. At its peak around 2 lakh students a year arrived, and the business was worth over 6,000 crore rupees. Bansal, in a wheelchair, kept teaching for decades and died in 2021 at 71.",
    meaning: "A single teacher who gets results can build an industry. But an economy built on one exam carries the weight of every teenager who sits it.",
    extra: ["Bansal Classes was formally founded in 1991, after his first students cleared the JEE.", "Student numbers fell sharply after 2023 amid concern over stress on students, and the town has been trying to change how it works.", "Many of Kota's top teachers today are its own former students, returned with IIT degrees."],
    facts: [["bansal"], ["1974", "muscular dystrophy"], ["dining table"], ["1983", "factory shut", "factory closed"], ["iit"], ["2 lakh", "6,000 crore"], ["kota"]],
    vocab: ["dystrophy", "institute", "entrance exam"] }
  );

